// Expects input to carry etsy[] and amazon[] image URLs from Research Agent.
// Falls back to top Etsy image URLs fetched via SerpAPI image search if not provided.
const input = $input.first().json;
const niche = input.niche || '';

const etsyImages   = (input.etsy   || []).map(i => i.image).filter(Boolean);
const amazonImages = (input.amazon || []).map(i => i.image).filter(Boolean);

const imageUrls = [...new Set([...etsyImages, ...amazonImages])].slice(0, 8);

if (imageUrls.length === 0) {
  return [{ json: { source: 'vision', niche, data: [], skipped: true, reason: 'no_images' } }];
}

return imageUrls.map((url, index) => ({ json: { niche, imageUrl: url, index } }));

const item = $input.first();
const ctx  = $('Prepare Image List').first().json;

// Binary data from the HTTP download
const binaryKey = Object.keys(item.binary || {})[0] || 'data';
const binary = item.binary?.[binaryKey];

if (!binary?.data) {
  throw new Error(`Failed to download image: ${ctx.imageUrl}`);
}

const mimeType  = binary.mimeType || 'image/jpeg';
const base64    = binary.data;

return [{
  json: {
    niche:     ctx.niche,
    imageUrl:  ctx.imageUrl,
    index:     ctx.index,
    base64,
    mimeType
  }
}];

