parameters.jsCode:
const items = $input.all();
const niche = $('Execute Workflow Trigger').first().json.niche;

const data = items.map((item, i) => {
  const raw   = item.json?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  const clean = raw.replace(/```json|```/g, '').trim();
  const match = clean.match(/\{[\s\S]*\}/);
  let analysis = {};
  try { analysis = JSON.parse(match?.[0] || '{}'); } catch (_) {}
  return { imageIndex: i, ...analysis };
}).filter(a => a.style || a.layout);

return [{ json: { source: 'vision', niche, data } }];
